SELECT o.id, o.order_no AS orderNo, o.amount_cent AS amountCent, o.payment_method AS paymentMethod, o.invoice_status AS invoiceStatus, o.deleted_at AS deletedAt, COALESCE(o.invoice_no, ib.invoice_no) AS invoiceNo, o.created_at AS createdAt, o.version, COALESCE(p.name, o.provider_name_snapshot) AS providerName, o.invoice_title_type_snapshot AS invoiceTitleType, o.invoice_title_name_snapshot AS invoiceTitleName, (SELECT ibo.batch_id FROM invoice_batch_order ibo JOIN invoice_batch ib ON ib.id = ibo.batch_id WHERE ibo.order_id = o.id AND ib.status = 'ISSUED' ORDER BY ib.id DESC LIMIT 1) AS invoiceBatchId FROM api_order o LEFT JOIN api_provider p ON p.id = o.provider_id LEFT JOIN invoice_batch_order ibo ON ibo.order_id = o.id LEFT JOIN invoice_batch ib ON ib.id = ibo.batch_id AND ib.status = 'ISSUED'
o.deleted_at IS NOT NULL o.deleted_at IS NULL
AND (o.order_no LIKE ('%' || #{keyword} || '%') OR p.name LIKE ('%' || #{keyword} || '%') OR o.provider_name_snapshot LIKE ('%' || #{keyword} || '%') OR COALESCE(o.invoice_no, ib.invoice_no) LIKE ('%' || #{keyword} || '%') OR o.invoice_title_name_snapshot LIKE ('%' || #{keyword} || '%'))
AND o.provider_id IN #{id}
AND o.invoice_status = #{invoiceStatus}
AND o.invoice_title_type_snapshot = #{invoiceTitleType}
ORDER BY o.created_at DESC LIMIT #{pageSize} OFFSET #{offset}

