o.deleted_at IS NOT NULL o.deleted_at IS NULL
AND (o.order_no LIKE ('%' || #{keyword} || '%') OR p.name LIKE ('%' || #{keyword} || '%') OR o.provider_name_snapshot LIKE ('%' || #{keyword} || '%') OR COALESCE(o.invoice_no, ib.invoice_no) LIKE ('%' || #{keyword} || '%') OR o.invoice_title_name_snapshot LIKE ('%' || #{keyword} || '%'))
AND o.provider_id IN #{id}
AND o.invoice_status = #{invoiceStatus}
AND o.invoice_title_type_snapshot = #{invoiceTitleType}

